-- State transitions declared for Booth: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION event.booths_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('available', 'available'), ('available', 'unavailable'), ('unavailable', 'available'), ('unavailable', 'unavailable'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: booths.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_booths__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS booths_state_transition_check ON event.booths;
CREATE TRIGGER booths_state_transition_check
    BEFORE UPDATE OF "state" ON event.booths
    FOR EACH ROW EXECUTE FUNCTION event.booths_state_transition_check();
